lessons.starter_code:
int count_multiples(int start, int end, int k) {
    // TODO: Count numbers between start and end divisible by k
    return 0;
}

lessons.solution_code:
int count_multiples(int start, int end, int k) {
    int count = 0;
    for (int i = start; i <= end; ++i) {
        if (i % k == 0) count++;
    }
    return count;
}

